// ============================================================================
//  fir_lpf  --  51-tap low-pass FIR, reference implementation
// ============================================================================
//  Runs directly on the AMC1306 chain output: one sample per `valid_in`,
//  same 62.5 kSPS rate, no clock-domain change.
//
//  Coefficients come from ../rtl/fir_coefs.vh, which is generated by
//  ../gen/amc1306_lpf_design.m (MATLAB) together with the Xilinx .coe file.
//  The integers there are 16-bit, scaled so that sum(coef) = 2^15; the DC gain
//  of the *integer* filter is therefore 2^15, and this module drops those 15
//  bits after the accumulator (SHIFT = 15).
//
//  >>> This module is the SIMULATION REFERENCE.  In the real build replace it
//  >>> with the Xilinx FIR Compiler IP loaded with amc1306_lpf_51tap.coe
//  >>> (see ../README.md section 4 for the exact GUI settings).  Both compute
//  >>> the same thing: full-precision MAC, then a 15-bit right shift and a
//  >>> 16-bit saturation.
//
//  Throughput: one sample per clock (the testbench drives it back-to-back).
//  Latency : 1 clock from valid_in to valid_out.
// ============================================================================

`timescale 1ps/1ps

module fir_lpf #(
    parameter integer TAPS   = 51,
    parameter integer DATA_W = 16,
    parameter integer COEF_W = 16,
    parameter integer SHIFT  = 15
)(
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire                     valid_in,
    input  wire signed [DATA_W-1:0] din,
    output reg                      valid_out,
    output reg  signed [DATA_W-1:0] dout
);

    // coefficient table, generated by MATLAB -- do not edit by hand
    reg signed [COEF_W-1:0] coef [0:TAPS-1];
    `include "fir_coefs.vh"

    // sample history: sr[0] is the newest sample
    reg signed [DATA_W-1:0] sr [0:TAPS-1];

    integer i;

    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            for (i = 0; i < TAPS; i = i + 1) sr[i] <= {DATA_W{1'b0}};
        end
        else if (valid_in) begin
            sr[0] <= din;
            for (i = 1; i < TAPS; i = i + 1) sr[i] <= sr[i-1];
        end

    // full-precision multiply-accumulate: 16x16 -> 32, 51 terms -> 48 bits
    reg signed [47:0] acc;
    integer k;

    always @* begin
        acc = din * coef[0];
        for (k = 1; k < TAPS; k = k + 1)
            acc = acc + sr[k-1] * coef[k];
    end

    wire signed [47:0] scaled = acc >>> SHIFT;

    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            valid_out <= 1'b0;
            dout      <= {DATA_W{1'b0}};
        end
        else begin
            valid_out <= valid_in;
            if (valid_in) begin
                if      (scaled >  48'sd32767) dout <= 16'sh7FFF;
                else if (scaled < -48'sd32768) dout <= 16'sh8000;
                else                           dout <= scaled[DATA_W-1:0];
            end
        end

endmodule
